function ClockWidget() {
  const [now, setNow] = useState(new Date());
  useEffect(() => {
    const t = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(t);
  }, []);
  return (
    <div style={{ fontSize: "14px", lineHeight: 1.3 }}>
      <div style={{ fontWeight: 700 }}>{now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</div>
      <div style={{ color: "var(--t3)", fontSize: "12px" }}>{now.toLocaleDateString(undefined, { weekday: "short", month: "short", day: "numeric" })}</div>
      <div style={{ color: "var(--t3)", fontSize: "12px" }}>Atlanta</div>
    </div>
  );
}

function RailColumn({ children, gridColumn = "span 3" }) {
  return (
    <div style={{ gridColumn, display: "flex", flexDirection: "column", gap: 14, minWidth: 0 }}>
      {children}
    </div>
  );
}

const GridCard = ({ title, icon, actions, children, style: styleProp, gridColumn }) => {
  const [isHovered, setIsHovered] = useState(false);

  const hoverGlow = isHovered 
    ? "0 0 0 2px rgba(255, 0, 13, 0.32), 0 10px 30px rgba(255, 0, 13, 0.2)" 
    : "none";

  return (
    <div
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      style={{
        gridColumn: gridColumn === false ? undefined : (gridColumn || "span 4"),
        position: "relative",
        borderRadius: "16px",
        padding: "3px",
        border: isHovered ? "1px solid rgba(255, 0, 13, 0.3)" : "1px solid rgba(255,255,255,0.09)",
        transition: "all 0.2s ease",
        boxShadow: hoverGlow,
        ...styleProp,
      }}
    >
      <div className="liquid-glass" style={{
        padding: "16px 18px",
        minHeight: "auto",
        display: "flex",
        flexDirection: "column",
        borderRadius: "14px",
      }}>
        {(title || icon || actions) && (
          <div style={{
            display: "flex",
            alignItems: "center",
            gap: 10,
            paddingBottom: 10,
            borderBottom: "1px solid rgba(255,255,255,0.08)",
            marginBottom: 10,
            flexShrink: 0,
          }}>
            {icon && <span style={{ fontSize: 18, color: "#ff000d" }}>{icon}</span>}
            {title && (
              <span style={{
                flex: 1,
                fontSize: "14.5px",
                fontWeight: 700,
                letterSpacing: ".04em",
                textTransform: "uppercase",
                color: "#ff000d",
              }}>
                {title}
              </span>
            )}
            {actions}
          </div>
        )}
        <div style={{ flex: 1, overflow: "hidden", fontSize: "14px", lineHeight: "1.45" }}>
          {children}
        </div>
      </div>
    </div>
  );
};

export default function DashboardPanel({ setActive }) {
  const dock = useAgentDockOptional();
  const [notes, setNotes] = useState(() => load("lifeos_dash_notes", ""));
  const [previousNotes, setPreviousNotes] = useState(load("lifeos_dash_previous_notes", []));
  const [products, setProducts] = useState(() => load("lifeos_dash_products", [
    { name: "Online Course", moRev: 12450, ytdRev: 87200, moSales: 42, ytdSales: 298 },
    { name: "1:1 Coaching", moRev: 9800, ytdRev: 65100, moSales: 11, ytdSales: 72 },
    { name: "Ebook Bundle", moRev: 3150, ytdRev: 21850, moSales: 185, ytdSales: 1240 },
  ]));
  const [editProducts, setEditProducts] = useState(false);
  const [productInputs, setProductInputs] = useState({});

  const [budgetDesc, setBudgetDesc] = useState("");
  const [budgetAmount, setBudgetAmount] = useState("");
  const [budgetItems, setBudgetItems] = useState(load("lifeos_dash_budget", []));

  const [financeInstitutions, setFinanceInstitutions] = useState(load("lifeos_dash_finance_institutions", [
    { name: "Sofi", checking: 8500, savings: 42000 },
    { name: "Stripe", checking: 2450, savings: 0 },
    { name: "Square", checking: 1120, savings: 0 },
    { name: "CashApp", checking: 680, savings: 320 },
    { name: "Venmo", checking: 290, savings: 0 },
    { name: "Paypal", checking: 1540, savings: 0 },
    { name: "OnePay", checking: 750, savings: 9800 },
  ]));
  const [editFinance, setEditFinance] = useState(false);
  const [financeInputs, setFinanceInputs] = useState({});
  const [editCredit, setEditCredit] = useState(false);
  const [credInput, setCredInput] = useState({});

  const [tasks, setTasks] = useState([]);
  const [links, setLinks] = useState(load("lifeos_dash_links", []));
  const [newLinkLabel, setNewLinkLabel] = useState("");
  const [newLinkUrl, setNewLinkUrl] = useState("");
  const [newTaskInput, setNewTaskInput] = useState("");
  const [leads, setLeads] = useState([]);

  const [social, setSocial] = useState(null);
  const [notifStream, setNotifStream] = useState([]);
  const [aiTips, setAiTips] = useState([]);
  const [aiLoading, setAiLoading] = useState(false);
  const [supabaseTodos, setSupabaseTodos] = useState([]);
  const [newSupabaseTodo, setNewSupabaseTodo] = useState("");
  const [financeSnap, setFinanceSnap] = useState(() => loadFinanceHubSnapshot());

  const [spencerOnline, setSpencerOnline] = useState(false);
  const [spencerOllama, setSpencerOllama] = useState(false);
  const [spencerBusy, setSpencerBusy] = useState(false);
  const [spencerInput, setSpencerInput] = useState("");
  const [spencerReply, setSpencerReply] = useState("");
  const [spencerErr, setSpencerErr] = useState("");

  const { user: fbUser } = useAuth();

  useEffect(() => {
    const poll = () => hermesHealth().then((h) => {
      setSpencerOnline(!!h.hermes || !!h.ollama);
      setSpencerOllama(!!h.ollama);
    });
    poll();
    const t = setInterval(poll, 15000);
    return () => clearInterval(t);
  }, []);

  useEffect(() => {
    refreshFinanceKv().then(setFinanceSnap);
    const iv = setInterval(() => refreshFinanceKv().then(setFinanceSnap), 90000);
    return () => clearInterval(iv);
  }, []);

  useEffect(() => {
    const acc = financeSnap.accounts || [];
    if (acc.length) {
      setFinanceInstitutions((prev) => {
        const merged = acc.map((a) => ({
          name: a.name || a.institution || "Account",
          checking: Number(a.checking ?? a.balance ?? 0) || 0,
          savings: Number(a.savings ?? 0) || 0,
        }));
        return merged.length ? merged : prev;
      });
    }
    if (financeSnap.credit?.karma) setCredInput((c) => ({ ...c, karma: financeSnap.credit.karma }));
    if (financeSnap.credit?.experian) setCredInput((c) => ({ ...c, exper: financeSnap.credit.experian }));
  }, [financeSnap]);

  useEffect(() => {
    kvGet("activity_events").then((d) => {
      const list = Array.isArray(d) ? d.slice(0, 12) : [];
      setNotifStream(list.map((e) => ({
        text: e.message || e.title || e.type || "Activity",
        ts: e.ts || e.created_at || e.at,
      })));
    });
  }, []);

  async function askSpencer() {
    const msg = spencerInput.trim();
    if (!msg || spencerBusy) return;
    setSpencerBusy(true);
    setSpencerErr("");
    try {
      const { text } = await hermesChat([{ role: "user", content: msg }]);
      setSpencerReply(text || "(empty response)");
      setSpencerInput("");
    } catch (e) {
      setSpencerErr(e.message || "Hermes offline — start gateway with LifeOS profile");
    } finally {
      setSpencerBusy(false);
    }
  }

  const go = id => setActive && setActive(id);

  function addBudget(desc, amount) {
    if (!desc.trim() || !amount) return;
    const next = [...budgetItems, { id: Date.now(), desc: desc.trim(), amount: Number(amount) || 0, paid: false }];
    setBudgetItems(next);
    save("lifeos_dash_budget", next);
  }

  function toggleBudgetPaid(id) {
    const next = budgetItems.map(item => item.id === id ? { ...item, paid: !item.paid } : item);
    setBudgetItems(next);
    save("lifeos_dash_budget", next);
  }

  function deleteBudget(id) {
    const next = budgetItems.filter(item => item.id !== id);
    setBudgetItems(next);
    save("lifeos_dash_budget", next);
  }

  function saveProducts() {
    if (editProducts) {
      const next = products.map((p, idx) => ({
        name: productInputs[`${idx}-name`] ?? p.name,
        moRev: Number(productInputs[`${idx}-moRev`] ?? p.moRev) || 0,
        ytdRev: Number(productInputs[`${idx}-ytdRev`] ?? p.ytdRev) || 0,
        moSales: Number(productInputs[`${idx}-moSales`] ?? p.moSales) || 0,
        ytdSales: Number(productInputs[`${idx}-ytdSales`] ?? p.ytdSales) || 0,
      }));
      setProducts(next);
      save("lifeos_dash_products", next);
      setProductInputs({});
    } else {
      const seed = {};
      products.forEach((p, idx) => {
        seed[`${idx}-name`] = p.name;
        seed[`${idx}-moRev`] = p.moRev;
        seed[`${idx}-ytdRev`] = p.ytdRev;
        seed[`${idx}-moSales`] = p.moSales;
        seed[`${idx}-ytdSales`] = p.ytdSales;
      });
      setProductInputs(seed);
    }
    setEditProducts(e => !e);
  }

  function saveFinanceInstitutions() {
    if (editFinance) {
      const next = financeInstitutions.map((inst, idx) => ({
        name: financeInputs[`${idx}-name`] ?? inst.name,
        checking: Number(financeInputs[`${idx}-checking`] ?? inst.checking) || 0,
        savings: Number(financeInputs[`${idx}-savings`] ?? inst.savings) || 0,
      }));
      setFinanceInstitutions(next);
      save("lifeos_dash_finance_institutions", next);
      setFinanceInputs({});
    } else {
      const seed = {};
      financeInstitutions.forEach((inst, idx) => {
        seed[`${idx}-name`] = inst.name;
        seed[`${idx}-checking`] = inst.checking;
        seed[`${idx}-savings`] = inst.savings;
      });
      setFinanceInputs(seed);
    }
    setEditFinance(e => !e);
  }

  async function addTask() {
    if (!newTaskInput.trim()) return;
    const current = await kvGet("tasks_queue") || [];
    const newT = { id: Date.now(), title: newTaskInput.trim(), done: false };
    const updated = [...current, newT];
    await kvSet("tasks_queue", updated);
    setTasks(updated.filter(t => !t.done).slice(0, 6));
    setNewTaskInput("");
  }

  async function deleteTask(id) {
    const current = await kvGet("tasks_queue") || [];
    const updated = current.filter(t => t.id !== id);
    await kvSet("tasks_queue", updated);
    setTasks(updated.filter(t => !t.done).slice(0, 6));
  }

  function addLink() {
    if (!newLinkLabel.trim() || !newLinkUrl.trim()) return;
    const u = [...links, { label: newLinkLabel.trim(), url: newLinkUrl.trim(), brand: "link" }];
    setLinks(u);
    save("lifeos_dash_links", u);
    setNewLinkLabel("");
    setNewLinkUrl("");
  }

  function deleteLink(idx) {
    const u = links.filter((_, i) => i !== idx);
    setLinks(u);
    save("lifeos_dash_links", u);
  }

  function saveNote() {
    if (!notes.trim()) return;
    setPreviousNotes(prev => {
      const next = [notes.trim(), ...prev];
      save("lifeos_dash_previous_notes", next);
      return next;
    });
    setNotes("");
    save("lifeos_dash_notes", "");
  }

  function removePrevious(idx) {
    setPreviousNotes(prev => {
      const next = prev.filter((_, i) => i !== idx);
      save("lifeos_dash_previous_notes", next);
      return next;
    });
  }

  const moneyTipsList = [
    "Post in local FB groups offering free value first.",
    "Offer a 15-min free audit to 5 local businesses/day.",
    "Create a simple lead magnet and pin it.",
    "Reply to 'looking for' posts with helpful non-sales answer.",
    "Record a 60s tip video for Instagram Reels.",
    "Partner with one complementary local business for cross promo.",
    "List your service on 3 free directories today.",
    "DM 10 people who liked similar posts with value.",
    "Host a free 20-min webinar on a pain point.",
    "Turn one client win into a case study post.",
    "Use Google My Business posts daily.",
    "Ask happy clients for referrals with a simple script.",
    "Comment thoughtfully on 20 industry posts.",
    "Create a free checklist and share in groups.",
    "Offer a limited 'founding member' discount to 3 people.",
    "Post before/after in local community pages.",
    "Run a poll in a relevant group to engage.",
    "Email 5 past clients with a quick win idea.",
    "Join 2 new relevant FB groups and introduce yourself helpfully.",
    "Turn a common question into a short guide."
  ];
  const lifeHacksList = [
    "Batch all non-urgent emails to 2x per day.",
    "Use the 2-minute rule for small tasks.",
    "Prep outfits the night before.",
    "Keep a 'done' list to boost motivation.",
    "Set phone to grayscale after 8pm.",
    "One-tab rule for focused work.",
    "Drink water before coffee.",
    "Walk while on calls when possible.",
    "Review tomorrow's calendar tonight.",
    "Say 'no' to one thing per day.",
    "Use voice notes for quick ideas.",
    "Clean your desk at end of day.",
    "Read 10 pages before bed.",
    "Meal prep Sundays for the week.",
    "Limit social media to 20 min blocks.",
    "Write 3 things you're grateful for daily.",
    "Stand up and stretch every 45 min.",
    "Keep a 'later' list for distractions.",
    "Turn off notifications during deep work.",
    "Celebrate small wins out loud."
  ];
  const getDaily = (list, count = 5) => {
    const day = new Date().getDate() + new Date().getMonth() * 31;
    const start = day % Math.max(1, list.length - count);
    return list.slice(start, start + count);
  };
  const getDailyMoneyTips = () => getDaily(moneyTipsList);
  const getDailyLifeHacks = () => getDaily(lifeHacksList);

  const karmaScore = Number(credInput.karma ?? financeSnap.credit?.karma) || 0;
  const experScore = Number(credInput.exper ?? financeSnap.credit?.experian) || 0;
  const creditAvg = financeSnap.credit?.avg || (karmaScore && experScore ? Math.round((karmaScore + experScore) / 2) : karmaScore || experScore || 0);
  const creditPct = Math.max(0, Math.min(100, ((creditAvg - 300) / 550) * 100));

